interface.definition:
a!localVariables(
  local!showtoggle:false(),
  {

    /* ── TITLE BAR ── */
    #"SYSTEM_SYSRULES_cardLayout"(
      contents: {
        #"SYSTEM_SYSRULES_sideBySideLayout"(
          alignVertical: "MIDDLE",
          items: {
            #"SYSTEM_SYSRULES_sideBySideItem"(
              width: "MINIMIZE",
              item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                marginBelow: "NONE",
                labelPosition: "COLLAPSED",
                value: {
                  #"SYSTEM_SYSRULES_richTextIcon"(
                    icon: "user",
                    size: "MEDIUM_PLUS"
                  )
                }
              )
            ),
            #"SYSTEM_SYSRULES_sideBySideItem"(
              item: #"SYSTEM_SYSRULES_headingField"(
                marginBelow: "NONE",
                text: "User Management",
                fontWeight: "SEMI_BOLD",
                size: "MEDIUM",
                headingTag: "H1"
              )
            ),
            #"SYSTEM_SYSRULES_sideBySideItem"(
              width: "MINIMIZE",
              item: #"SYSTEM_SYSRULES_recordActionField_v1"(
                actions: #"SYSTEM_SYSRULES_recordActionItem"(
                  action: #"urn:appian:record-action:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/e71824be-e81d-4b7a-88e2-77dc857a4efe"
                ),
                style: "CALL_TO_ACTION",
                align: "END"
              )
            )
          }
        )
      },
      height: "AUTO",
      style: "ACCENT",
      padding: "STANDARD",
      marginBelow: "NONE",
      showBorder: false
    ),

    /* ── CONTENT AREA ── */
    #"SYSTEM_SYSRULES_columnsLayout"(
      columns: {
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {

            #"SYSTEM_SYSRULES_cardLayout"(
              contents: {
                #"SYSTEM_SYSRULES_toggleField"(
                  choiceLabel: "Show The Inactive Users",
                  value: local!showtoggle,
                  saveInto: local!showtoggle,
                  marginBelow: "STANDARD"
                ),
                #"SYSTEM_SYSRULES_gridField_v5"(
                  label: "User Details",
                  labelPosition: "COLLAPSED",
                  data: #"SYSTEM_SYSRULES_recordData"(
                    recordType: #"urn:appian:record-type:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc",
                    filters: {
                      #"SYSTEM_SYSRULES_queryFilter"(
                        field: #"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/811b9c80-c907-4d49-9262-702a73d2e7d1",
                        operator: "=",
                        value: not(local!showtoggle)
                      )
                    }
                  ),
                  showRefreshButton: true,
                  showSearchBox: true,
                  columns: {
                    /* ID */
                    #"SYSTEM_SYSRULES_gridColumn"(
                      label: "Id",
                      value: text(
                        fv!row[#"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/b9c974e1-800e-4dfe-9d43-14273008fe48"],
                        "#00000"
                      ),
                      sortField: #"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/b9c974e1-800e-4dfe-9d43-14273008fe48",
                      width: "NARROW"
                    ),
                    /* First Name */
                    #"SYSTEM_SYSRULES_gridColumn"(
                      label: "First Name",
                      value: a!defaultValue(
                        fv!row[#"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/432735ea-6585-464d-b6e4-77009d9bcf1d"],
                        "–"
                      ),
                      sortField: #"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/432735ea-6585-464d-b6e4-77009d9bcf1d"
                    ),
                    /* Last Name */
                    #"SYSTEM_SYSRULES_gridColumn"(
                      label: "Last Name",
                      value: a!defaultValue(
                        fv!row[#"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/347f4da4-04e1-4eb5-b521-564f0e8be776"],
                        "–"
                      ),
                      sortField: #"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/347f4da4-04e1-4eb5-b521-564f0e8be776"
                    ),

                    /* Username */
                    #"SYSTEM_SYSRULES_gridColumn"(
                      label: "Username",
                      value: a!defaultValue(
                        fv!row[#"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/b6956f1b-0674-4b2a-a808-051a41257c01"],
                        "–"
                      ),
                      sortField: #"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/b6956f1b-0674-4b2a-a808-051a41257c01"
                    ),
                    /* Status */
                    #"SYSTEM_SYSRULES_gridColumn"(
                      label: "Status",
                      value: #"SYSTEM_SYSRULES_richTextDisplayField"(
                        labelPosition: "COLLAPSED",
                        value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                          text: if(
                            fv!row[#"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/811b9c80-c907-4d49-9262-702a73d2e7d1"] = true(),
                            "● Active",
                            "● Inactive"
                          ),
                          style: "STRONG",
                          color: if(
                            fv!row[#"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/811b9c80-c907-4d49-9262-702a73d2e7d1"] = true(),
                            "POSITIVE",
                            "SECONDARY"
                          )
                        )
                      ),
                      sortField: #"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/811b9c80-c907-4d49-9262-702a73d2e7d1",
                      width: "NARROW"
                    ),
                    /* Created By */
                    #"SYSTEM_SYSRULES_gridColumn"(
                      label: "Created By",
                      value: if(
                        a!isNullOrEmpty(
                          fv!row[#"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/7791c860-1d5f-4680-b36f-ba0a1b2285b5"]
                        ),
                        "–",
                        #"_a-0000eef8-4604-8000-9e54-011c48011c48_1121809"(
                          fv!row[#"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/7791c860-1d5f-4680-b36f-ba0a1b2285b5"]
                        )
                      ),
                      sortField: #"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/7791c860-1d5f-4680-b36f-ba0a1b2285b5"
                    ),
                    /* Edit Action — pencil */
                    #"SYSTEM_SYSRULES_gridColumn"(
                      label: "Actions",
                        value: #"SYSTEM_SYSRULES_recordActionField_v1"(
                          actions: {
                            #"SYSTEM_SYSRULES_recordActionItem"(
                              action: #"urn:appian:record-action:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/46040161-915c-41e6-a5eb-7a886fe070d2",
                              identifier: fv!identifier
                            ),
                            #"SYSTEM_SYSRULES_recordActionItem"(
                              action: #"urn:appian:record-action:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/d3978ca9-c451-44cd-a715-3a2eebf0265e",
                              identifier: fv!identifier
                            )
                          },
                          style: "MENU_ICON"
                        ),

                      width: "NARROW",
                      align: "CENTER"
                    )

                  },
                  rowHeader: 2,
                  borderStyle: "LIGHT",
                  refreshAfter: "RECORD_ACTION",
                  validations: {}
                )
              },
              height: "AUTO",
              style: "NONE",
              shape: "SEMI_ROUNDED",
              padding: "STANDARD",
              marginBelow: "STANDARD",
              showBorder: false,
              showShadow: true
            )
          }
        )
      }
    )
  }
)
